create table if not exists gl_codes(code text primary key,description text not null);\ncreate table if not exists budgets(id bigint generated always as identity primary key,gl_code text references gl_codes(code),amount numeric(12,2) not null default 0,comments text,prior_budget numeric(12,2),prior_actual numeric(12,2),unique(gl_code));\ncreate table if not exists actuals(id bigint generated always as identity primary key,date date not null,gl_code text references gl_codes(code),amount numeric(12,2) not null,description text,school_month int,unique(date,gl_code,amount,description));\ncreate table if not exists bank_transactions(id bigint generated always as identity primary key,date date not null,transaction text not null,withdrawal numeric(12,2) default 0,deposit numeric(12,2) default 0,balance numeric(12,2),gl_code text references gl_codes(code),description text,amount numeric(12,2) default 0,unique(date,transaction,amount,description));\ncreate table if not exists cheques(id bigint generated always as identity primary key,cheque_no text not null,gl_code text references gl_codes(code),amount numeric(12,2) not null,cheque_date date not null,cleared_date date,vendor text,description text,invoice_no text,unique(cheque_no,amount,cheque_date));\nalter table gl_codes enable row level security;alter table budgets enable row level security;alter table actuals enable row level security;alter table bank_transactions enable row level security;alter table cheques enable row level security;\n